insert into public.v2_vehicle_technical_sources(company_id,vehicle_id,source_key,source_type,title,publisher,publication_year,source_url,authority_level,applicability_status,access_status,verification_status,notes,source_metadata)
select v.company_id,v.id,s.source_key,s.source_type,s.title,s.publisher,s.publication_year,s.source_url,s.authority_level,s.applicability_status,s.access_status,s.verification_status,s.notes,s.source_metadata
from src s join public.v2_vehicles v on upper(replace(v.plate,'-',''))=s.plate
on conflict(company_id,vehicle_id,source_key) do update set source_type=excluded.source_type,title=excluded.title,publisher=excluded.publisher,publication_year=excluded.publication_year,source_url=excluded.source_url,authority_level=excluded.authority_level,applicability_status=excluded.applicability_status,access_status=excluded.access_status,verification_status=excluded.verification_status,notes=excluded.notes,source_metadata=excluded.source_metadata,updated_at=now();

-- VW 9.150 EOD / MWM 4.12 TCE: C 17 308, WK 962/13, W 962.
update public.v2_vehicle_components c set data_status='verified',source_metadata=coalesce(c.source_metadata,'{}'::jsonb)||jsonb_build_object('verification_source_key','mann_filters_vw_9150eod_mwm412_v3','catalog_application','VW 9.150 E OD / MWM 4.12 TCAE / 04-2004 to 12-2012','catalog_reference_verified',true,'physical_fitment_verified',false,'purchase_gate','confirm housing/installed filter before purchase','verified_at','2026-09-27'),updated_at=now()
from public.v2_vehicle_component_links l join public.v2_vehicles v on v.id=l.vehicle_id where l.component_id=c.id and v.plate='CPI6C79' and c.name in ('Filtro de ar do motor','Filtro principal de combustivel','Filtro de oleo do motor');
update public.v2_vehicle_components c set source_metadata=coalesce(c.source_metadata,'{}'::jsonb)||jsonb_build_object('mann_part_number','WK 962/13','mwm_original_numbers',jsonb_build_array('9.0541.15.1.0027','905411510042','905411510028')) from public.v2_vehicle_component_links l join public.v2_vehicles v on v.id=l.vehicle_id where l.component_id=c.id and v.plate='CPI6C79' and c.name='Filtro principal de combustivel';
update public.v2_vehicle_components c set source_metadata=coalesce(c.source_metadata,'{}'::jsonb)||jsonb_build_object('mann_part_number','C 17 308','vw_original_numbers',jsonb_build_array('2RD 129 620','2VC 129 619','2TA 129 619','2R0 129 620 D')) from public.v2_vehicle_component_links l join public.v2_vehicles v on v.id=l.vehicle_id where l.component_id=c.id and v.plate='CPI6C79' and c.name='Filtro de ar do motor';

