update public.v2_vehicle_components c set data_status='verified',source_metadata=coalesce(c.source_metadata,'{}'::jsonb)||jsonb_build_object('verification_source_key','tecfil_filters_volare_a6_2000_v3','catalog_application','Volare A6 / MWM 4.07 TCA / 01-2000 to 12-2001','catalog_reference_verified',true,'physical_fitment_verified',false,'purchase_gate','confirm installed housing/filter before purchase','verified_at','2026-09-27'),updated_at=now()
from public.v2_vehicle_component_links l join public.v2_vehicles v on v.id=l.vehicle_id where l.component_id=c.id and v.plate='MBJ1166' and c.name in ('Filtro de ar','Elemento de seguranca do filtro de ar','Filtro de oleo','Filtro de combustivel','Separador de agua');
update public.v2_vehicle_components c set source_metadata=coalesce(c.source_metadata,'{}'::jsonb)||jsonb_build_object('cross_references',jsonb_build_array('MANN W 1323','MWM 905411880018','MWM 905411880026','Agrale 6008001204004','VW 062115561A')) from public.v2_vehicle_component_links l join public.v2_vehicles v on v.id=l.vehicle_id where l.component_id=c.id and v.plate='MBJ1166' and c.name='Filtro de oleo';
update public.v2_vehicle_components c set source_metadata=coalesce(c.source_metadata,'{}'::jsonb)||jsonb_build_object('cross_references',jsonb_build_array('MANN WK 842/3','Volare/Agrale original 6008.006.035.00.7')) from public.v2_vehicle_component_links l join public.v2_vehicles v on v.id=l.vehicle_id where l.component_id=c.id and v.plate='MBJ1166' and c.name='Filtro de combustivel';
update public.v2_vehicle_components c set source_metadata=coalesce(c.source_metadata,'{}'::jsonb)||jsonb_build_object('assembly_note','Tecfil row lists PSD970/1 with CSD01 cup for 01/2000-12/2001 A6') from public.v2_vehicle_component_links l join public.v2_vehicles v on v.id=l.vehicle_id where l.component_id=c.id and v.plate='MBJ1166' and c.name='Separador de agua';

-- Mercedes 608 / OM314 service filters.
update public.v2_vehicle_components c set data_status='verified',source_metadata=coalesce(c.source_metadata,'{}'::jsonb)||jsonb_build_object('verification_source_key','mann_filters_mercedes_608_om314_v3','catalog_application','Mercedes 608 / OM314','catalog_reference_verified',true,'physical_fitment_verified',false,'purchase_gate','confirm installed filter housing/element before purchase','verified_at','2026-09-27'),updated_at=now()
from public.v2_vehicle_component_links l join public.v2_vehicles v on v.id=l.vehicle_id where l.component_id=c.id and v.plate='BYH8J61' and c.name in ('Filtro de ar seco','Elemento de seguranca do filtro de ar','Filtro de combustivel','Pre-filtro de combustivel','Filtro de oleo');

-- Fras-le catalog options: lining only, never the whole clutch disc.
with ins(name,mpn,thickness_mm,holes_pass,holes_countersunk,notes) as (values
 ('Revestimento de embreagem Fras-le RC/716','RC/716',3.50,18,12,'608 OM-314 85 CV, Sachs, 250 x 165 mm; inspect installed variant.'),
 ('Revestimento de embreagem Fras-le RC/913','RC/913',4.20,20,20,'608 OM-314, all, Sachs, 250 x 165 mm; inspect installed variant.'))
insert into public.v2_vehicle_components(group_code,name,generic_name,oem_brand,manufacturer_part_number,location_description,function_description,data_status,component_type,dimensions_spec,replacement_notes,source_metadata)
select 'transmission',i.name,'revestimento/lona do disco de embreagem','Fras-le',i.mpn,'Disco de embreagem, entre motor e cambio','Material de atrito rebitado no disco; not a complete disc assembly','verified','consumable',jsonb_build_object('outer_diameter_mm',250,'inner_diameter_mm',165,'thickness_mm',i.thickness_mm,'through_holes',i.holes_pass,'countersunk_holes',i.holes_countersunk,'system','Sachs'),jsonb_build_array('Confirmar espessura, furacao e sistema instalado','Nao tratar como kit/disco completo'),jsonb_build_object('seed','fleet_service_parts_verification_v3','verification_source_key','frasle_clutch_lining_608_om314_v3','catalog_reference_verified',true,'physical_fitment_verified',false,'orderable',false,'notes',i.notes)
from ins i where not exists(select 1 from public.v2_vehicle_components c where c.manufacturer_part_number=i.mpn and c.source_metadata->>'verification_source_key'='frasle_clutch_lining_608_om314_v3');
insert into public.v2_vehicle_component_applications(component_id,chassis_family,chassis_variant,engine_family,engine_code,notes,fitment_status,source_metadata)
select c.id,'Mercedes-Benz 608','LO 608','Mercedes-Benz OM314','OM314','Catalog reference verified; installed lining not physically confirmed.','candidate',jsonb_build_object('source_key','frasle_clutch_lining_608_om314_v3','physical_confirmation_required',true) from public.v2_vehicle_components c where c.source_metadata->>'verification_source_key'='frasle_clutch_lining_608_om314_v3' and not exists(select 1 from public.v2_vehicle_component_applications a where a.component_id=c.id and a.chassis_variant='LO 608');
insert into public.v2_vehicle_component_links(company_id,vehicle_id,component_id,fitment_status,notes)
select v.company_id,v.id,c.id,'candidate','Fras-le catalog application to 608 OM314; confirm installed clutch dimensions.' from public.v2_vehicles v cross join public.v2_vehicle_components c where v.plate='BYH8J61' and c.source_metadata->>'verification_source_key'='frasle_clutch_lining_608_om314_v3' on conflict(company_id,vehicle_id,component_id) do nothing;
with target_view as (select ev.id from public.v2_vehicle_exploded_views ev where ev.group_code='transmission' and (ev.source_metadata->>'plate'='BYH8J61' or ev.chassis_variant ilike '%30830311268441%' or ev.chassis_variant='LO 608') order by case when ev.source_metadata->>'plate'='BYH8J61' then 0 else 1 end,ev.created_at limit 1), numbered as (select c.id,row_number() over(order by c.manufacturer_part_number) rn from public.v2_vehicle_components c where c.source_metadata->>'verification_source_key'='frasle_clutch_lining_608_om314_v3')
insert into public.v2_vehicle_exploded_view_items(exploded_view_id,component_id,item_number,quantity,component_type,position_note,exactness_status,source_metadata)
select tv.id,n.id,'CAT-CLUTCH-'||lpad(n.rn::text,2,'0'),1,'consumable','Catalog-option lining; physical fitment pending','verified',jsonb_build_object('source_key','frasle_clutch_lining_608_om314_v3','catalog_position_internal',true) from target_view tv cross join numbered n where not exists(select 1 from public.v2_vehicle_exploded_view_items e where e.exploded_view_id=tv.id and e.component_id=n.id);

update public.v2_vehicle_technical_profiles p set source_metadata=coalesce(p.source_metadata,'{}'::jsonb)||jsonb_build_object('service_parts_research_version','v3','service_parts_reviewed_at','2026-09-27','service_parts_policy','catalog reference verified != physical fitment verified'),updated_at=now() from public.v2_vehicles v where p.vehicle_id=v.id and v.plate in ('CPI6C79','MBJ1166','BYH8J61','EJW6A76');
